<template><section class="builder-panel controls-panel"><header class="builder-panel__heading"><strong>⌘ Test & Controls</strong><small>Browser only</small></header><div class="test-grid"><button v-for="item in tests" :key="item.type" @click="$emit('test',item)">{{ item.icon }} {{ item.label }}</button><button @click="$emit('undo')">↶ Undo</button><button @click="$emit('redo')">↷ Redo</button><button @click="$emit('reset-scene')">↻ Reset Scene</button><button @click="$emit('reset-all')">⌫ Reset Full Demo</button></div><div class="control-toggles"><label><input :checked="paused" type="checkbox" @change="$emit('pause',$event.target.checked)"> Pause animations</label><label><input :checked="grid" type="checkbox" @change="$emit('grid',$event.target.checked)"> Grid</label><label><input :checked="snapping" type="checkbox" @change="$emit('snapping',$event.target.checked)"> Snapping</label><label><input :checked="safeZone" type="checkbox" @change="$emit('safe-zone',$event.target.checked)"> Safe Zone</label></div></section></template>
<script setup>defineProps({paused:Boolean,grid:Boolean,snapping:Boolean,safeZone:Boolean});defineEmits(['test','pause','grid','snapping','safe-zone','undo','redo','reset-scene','reset-all']);const tests=[['stream.follow','alerts','♥','Test Follow'],['stream.subscription','subscription-alert','★','Test Subscription'],['stream.raid','raid-alert','⚡','Test Raid'],['achievement.unlocked','achievement','🏆','Test Achievement'],['community.event.upcoming','upcoming-event','▣','Test Event'],['tts.requested','tts','▥','Test TTS']].map(([type,targetWidgetType,icon,label])=>({id:`test-${type}`,type,targetWidgetType,platform:type.startsWith('stream')||type.startsWith('tts')?'twitch':'respawn',actor:'Demo Creator',summary:label,createdAtLabel:'just now',payload:{demo:true},icon,label}))</script>
